/**
 * Deterministic pseudo-random numbers for synthetic data.
 *
 * The same seed produces the same sequence on every machine, so a dataset can be
 * regenerated byte for byte and two rule settings can be compared on identical records.
 * `fork(label)` derives an independent stream, which keeps one section of the generator
 * from shifting every value after it when someone adds a new random draw.
 */
export interface Rng {
  /** Uniform number in [0, 1). */
  next(): number;
  /** Integer in [min, maxInclusive]. */
  int(min: number, maxInclusive: number): number;
  /** One element of a non-empty list. */
  pick<T>(items: readonly T[]): T;
  /** A key chosen with probability proportional to its weight. */
  weighted<K extends string>(weights: Readonly<Record<K, number>>): K;
  /** True with probability p. */
  chance(p: number): boolean;
  /** Poisson-distributed count (Knuth's method, fine for small lambda). */
  poisson(lambda: number): number;
  /** A shuffled copy (Fisher-Yates). */
  shuffle<T>(items: readonly T[]): T[];
  /** An independent stream derived from this one's seed and a label. */
  fork(label: string): Rng;
}

/** FNV-1a 32-bit hash. Used to turn labels into seeds. */
export function hashString(value: string): number {
  let hash = 0x811c9dc5;
  for (let i = 0; i < value.length; i++) {
    hash ^= value.charCodeAt(i);
    hash = Math.imul(hash, 0x01000193);
  }
  return hash >>> 0;
}

export function createRng(seed: number): Rng {
  let state = seed >>> 0;

  // mulberry32: small, fast and good enough for synthetic data (not for cryptography).
  const next = (): number => {
    state = (state + 0x6d2b79f5) >>> 0;
    let t = state;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };

  const rng: Rng = {
    next,
    int(min, maxInclusive) {
      if (maxInclusive < min) throw new RangeError(`int(${min}, ${maxInclusive}): empty range`);
      return min + Math.floor(next() * (maxInclusive - min + 1));
    },
    pick(items) {
      if (items.length === 0) throw new RangeError("pick() from an empty list");
      return items[Math.floor(next() * items.length)] as (typeof items)[number];
    },
    weighted(weights) {
      const entries = Object.entries(weights) as [keyof typeof weights, number][];
      const total = entries.reduce((sum, [, w]) => sum + Math.max(0, w), 0);
      if (total <= 0) throw new RangeError("weighted() needs at least one positive weight");
      let roll = next() * total;
      for (const [key, weight] of entries) {
        roll -= Math.max(0, weight);
        if (roll < 0) return key;
      }
      return (entries[entries.length - 1] as [keyof typeof weights, number])[0];
    },
    chance(p) {
      return next() < p;
    },
    poisson(lambda) {
      if (lambda <= 0) return 0;
      const limit = Math.exp(-lambda);
      let k = 0;
      let product = next();
      while (product > limit) {
        k++;
        product *= next();
      }
      return k;
    },
    shuffle(items) {
      const copy = [...items];
      for (let i = copy.length - 1; i > 0; i--) {
        const j = Math.floor(next() * (i + 1));
        [copy[i], copy[j]] = [copy[j] as (typeof copy)[number], copy[i] as (typeof copy)[number]];
      }
      return copy;
    },
    fork(label) {
      return createRng(hashString(`${seed}:${label}`));
    },
  };
  return rng;
}
